  padding: 0 22px 0 7px;
}

.context-view-toggle:hover,
.context-theme-toggle:hover {
  border-color: var(--accent-border);
  color: var(--accent);
}

/* Keep the label and geometry stable; only the background and border pulse. */
.context-view-toggle.is-attention {
  --latest-emphasis-bg: color-mix(in srgb, var(--accent) 24%, var(--surface-muted));
  --latest-emphasis-border: color-mix(in srgb, var(--accent) 76%, var(--line));
  background-color: var(--latest-emphasis-bg);
  border-color: var(--latest-emphasis-border);
  animation: context-latest-pulse 2s ease-in-out infinite;
}

@keyframes context-latest-pulse {
  0%, 100% { background-color: var(--accent-soft); border-color: var(--accent-border); }
  50% { background-color: var(--latest-emphasis-bg); border-color: var(--latest-emphasis-border); }
}

.context-view-toggle.is-attention:is(:hover, :focus-visible) { animation: none; }

@media (prefers-reduced-motion: reduce) {
  .context-view-toggle.is-attention { animation: none; }
}

